B.V0=s([B.P5,B.P7,B.Pa,B.Pi,B.Pd,B.Po],t.J)
B.OW=new A.cN("Captain Lorenzo",B.V0)
B.Xs=s(["The British officer drove his blade into you and threw you overboard.","Through fading vision, you watched the British naval ship sail away and leave you to the sea."],t.s)
B.Ov=new A.cv("Wake up","intro_return_to_stranger",!0,!1)
